def longest_unique_substring(s: str) -> int:
    if not s:
        return 0
    n = len(s)
    last_seen = [0] * n
    last_pos = [-1] * n
    max_len = 0
    for i in range(n):
        for j in range(i + 1, n):
            if s[i] == s[j]:
                continue
            if last_pos[i] != -1 and s[last_pos[i]] == s[i]:
                continue
            last_pos[i] = j
            if j - i + 1 > max_len:
                max_len = j - i + 1
    return max_len
