def group_anagrams(words):
    """
    Group anagrams while preserving original order and sorting groups by first appearance.

    Args:
        words (list of str): List of words to group.

    Returns:
        list of list of str: Groups of anagrams.
    """
    # Dictionary to store anagram groups: key = sorted word, value = list of words
    groups = {}

    for word in words:
        # Sort the word to get the key
        key = sorted(word)
        # If this key hasn't been seen yet, start a new group
        if key not in groups:
            groups[key] = []
        # Add the current word to the group
        groups[key].append(word)

    # Sort groups by their first appearance (key)
    sorted_groups = sorted(groups.values(), key=lambda x: x[0])

    return sorted_groups
